57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Dedicated audit logger; a successful create emits one line here. */
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
70	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
113	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
114	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        HttpHeaders headers = new HttpHeaders();
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        String address = normalizeAddress(owner.getAddress());
123	        if (address.isEmpty()) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        owner.setAddress(address);
127	        if (owner.getEmail() != null) {
128	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
129	            if (!EMAIL_PATTERN.matcher(email).matches()) {
130	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	            }
132	            owner.setEmail(email);
133	        }
134	        String telephone = normalizeTelephone(owner.getTelephone());
135	        if (telephone == null) {
136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
137	        }
138	        owner.setTelephone(telephone);
139	        LocalDate registrationDate = resolveRegistrationDate(owner.getRegistrationDate());
140	        owner.setRegistrationDate(registrationDate);
141	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
142	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
143	        }
144	        owner.setIdentityKey(identityKey(owner));
145	        if (isDuplicate(owner)) {
146	            return new ResponseEntity<>(HttpStatus.CONFLICT);
147	        }
148	        if (countOwnersInCity(owner.getCity()) >= 50) {
149	            return new ResponseEntity<>(HttpStatus.CONFLICT);
150	        }
151	        assignRegistrationAttributes(owner);
152	        this.clinicService.saveOwner(owner);
153	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
154	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
157	        headers.setLocation(UriComponentsBuilder.newInstance()
158	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
159	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
165	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
166	        if (currentOwner == null) {
167	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
168	        }
169	        currentOwner.setAddress(ownerFieldsDto.getAddress());
170	        currentOwner.setCity(ownerFieldsDto.getCity());
171	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
172	        currentOwner.setLastName(ownerFieldsDto.getLastName());
173	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
174	        String email = ownerFieldsDto.getEmail();
175	        if (email != null) {
176	            email = email.trim().toLowerCase(Locale.ROOT);
177	            if (!EMAIL_PATTERN.matcher(email).matches()) {
178	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
179	            }
180	        }
181	        currentOwner.setEmail(email);
182	        this.clinicService.saveOwner(currentOwner);
183	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Transactional
188	    @Override
189	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
190	        Owner owner = this.clinicService.findOwnerById(ownerId);
191	        if (owner == null) {
192	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	        }
194	        this.clinicService.deleteOwner(owner);
195	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
201	        Owner owner = this.clinicService.findOwnerById(ownerId);
202	        if (owner == null) {
203	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	        }
205	        HttpHeaders headers = new HttpHeaders();
206	        Pet pet = petMapper.toPet(petFieldsDto);
207	        owner.setId(ownerId);
208	        pet.setOwner(owner);
209	        pet.getType().setName(null);
210	        this.clinicService.savePet(pet);
211	        PetDto petDto = petMapper.toPetDto(pet);
212	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
213	            .buildAndExpand(pet.getId()).toUri());
214	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
215	    }
216	
217	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
218	    @Override
219	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
220	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
221	        if (currentOwner != null) {
222	            Pet currentPet = this.clinicService.findPetById(petId);
223	            if (currentPet != null) {
224	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
225	                currentPet.setName(petFieldsDto.getName());
226	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
227	                this.clinicService.savePet(currentPet);
228	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
229	            }
230	        }
231	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	    }
233	
234	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
235	    @Override
236	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
237	        HttpHeaders headers = new HttpHeaders();
238	        Visit visit = visitMapper.toVisit(visitFieldsDto);
239	        Pet pet = new Pet();
240	        pet.setId(petId);
241	        visit.setPet(pet);
242	        this.clinicService.saveVisit(visit);
243	        VisitDto visitDto = visitMapper.toVisitDto(visit);
244	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
245	            .buildAndExpand(visit.getId()).toUri());
246	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
247	    }
248	
249	
250	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
251	    @Override
252	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
253	        Owner owner = this.clinicService.findOwnerById(ownerId);
254	        if (owner != null) {
255	            Pet pet = owner.getPet(petId);
256	            if (pet != null) {
257	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
258	            }
259	        }
260	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
261	    }
262	
263	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
264	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
265	
266	    /**
267	     * Required national-number length per country code: '+61' (Australia) expects 9 national
268	     * digits and '+1' (NANP) expects 10. A number whose country code is listed here but whose
269	     * national part is not the required length is rejected.
270	     */
271	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
272	        "+61", 9, "+1", 10);
273	
274	    /**
275	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
276	     * code are kept when present; otherwise country code '+61' is assumed and a single
277	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
278	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
279	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
280	     * Returns {@code null} when the number cannot form a valid E.164 value.
281	     */
282	    private static String normalizeTelephone(String telephone) {
283	        if (telephone == null) {
284	            return null;
285	        }
286	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
287	        String e164;
288	        if (cleaned.startsWith("+")) {
289	            e164 = cleaned;
290	        } else {
291	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
292	            e164 = "+61" + national;
293	        }
294	        if (!E164_PATTERN.matcher(e164).matches()) {
295	            return null;
296	        }
297	        return hasValidNationalNumberLength(e164) ? e164 : null;
298	    }
299	
300	    /**
301	     * Whether the national number of a well-formed E.164 value has the length required for its
302	     * country code. Country codes not listed in {@link #NATIONAL_NUMBER_LENGTHS} carry no
303	     * per-country length rule and are accepted.
304	     */
305	    private static boolean hasValidNationalNumberLength(String e164) {
306	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
307	            String countryCode = entry.getKey();
308	            if (e164.startsWith(countryCode)) {
309	                return e164.length() - countryCode.length() == entry.getValue();
310	            }
311	        }
312	        return true;
313	    }
314	
315	    /**
316	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
317	     * code, membership number, household id, namesake count and household member count. Each is
318	     * derived from the owner's already-normalized fields and the existing owner population, so this
319	     * must run before the owner is saved, while the counts still exclude the owner being created.
320	     */
321	    private void assignRegistrationAttributes(Owner owner) {
322	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
323	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
324	        owner.setHouseholdId(householdId(owner));
325	        owner.setNamesakeCount(countNamesakes(owner));
326	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
327	    }
328	
329	    /**
330	     * Build the customer code '<CITY3>-<LAST3>-<NNNN>': CITY3 is the upper-cased first three
331	     * letters of {@code city}, LAST3 the upper-cased first three letters of {@code lastName},
332	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
333	     * owners already registered in that city (e.g. 'SYD-SMI-0007').
334	     */
335	    private String generateCustomerCode(String city, String lastName) {
336	        String city3 = firstThreeLetters(city);
337	        String last3 = firstThreeLetters(lastName);
338	        int sequence = countOwnersInCity(city) + 1;
339	        return String.format("%s-%s-%04d", city3, last3, sequence);
340	    }
341	
342	    /** The upper-cased first three letters (ignoring non-letters) of {@code value}. */
343	    private static String firstThreeLetters(String value) {
344	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
345	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
346	    }
347	
348	    /**
349	     * The number of existing owners registered in {@code city}, compared case-insensitively
350	     * with collapsed whitespace.
351	     */
352	    private int countOwnersInCity(String city) {
353	        String normalized = normalizeHouseholdField(city);
354	        return (int) this.clinicService.findAllOwners().stream()
355	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
356	            .count();
357	    }
358	
359	    /**
360	     * The effective registration date to store for a new owner: the date supplied on the request
361	     * when present, otherwise the current server date, in either case rolled forward to a business
362	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
363	     * This single point of resolution is what every registration-date-derived value (the stored
364	     * date, the membership number's year segment, the per-day create-limit) is computed from.
365	     */
366	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
367	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
368	        return toBusinessDay(date);
369	    }
370	
371	    /**
372	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
373	     * following Monday; a weekday is returned unchanged.
374	     */
375	    private static LocalDate toBusinessDay(LocalDate date) {
376	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
377	            date = date.plusDays(1);
378	        }
379	        return date;
380	    }
381	
382	    /**
383	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
384	     * {@code registrationDate} year (e.g. 'SMI-0007-M26').
385	     */
386	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
387	        String yy = String.format("%02d", registrationDate.getYear() % 100);
388	        return customerCode + "-M" + yy;
389	    }
390	
391	    /**
392	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
393	     * last name, compared case-insensitively.
394	     */
395	    private int countNamesakes(Owner owner) {
396	        String firstName = normalizeHouseholdField(owner.getFirstName());
397	        String lastName = normalizeHouseholdField(owner.getLastName());
398	        return (int) this.clinicService.findAllOwners().stream()
399	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
400	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
401	            .count();
402	    }
403	
404	    /**
405	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
406	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
407	     * unusually high daily signup volume.
408	     */
409	    private boolean isBulkSignupWarning() {
410	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
411	    }
412	
413	    /** The number of existing owners whose registration date is {@code date}. */
414	    private int countOwnersRegisteredOn(LocalDate date) {
415	        return (int) this.clinicService.findAllOwners().stream()
416	            .filter(existing -> date.equals(existing.getRegistrationDate()))
417	            .count();
418	    }
419	
420	    /**
421	     * The single derived key all duplicate detection flows through, formed from the owner's
422	     * already-normalized fields as {@code normalizedTelephone + '|' + (email or empty) + '|' +
423	     * (householdId or empty)}. It is computed at the create-time identity gate, before the household
424	     * id is derived, so the household segment is empty at that point. Because the telephone is part
425	     * of the key, two owners in the same household with different telephones resolve to different
426	     * keys and are both allowed.
427	     */
428	    private static String identityKey(Owner owner) {
429	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
430	        String email = owner.getEmail() == null ? "" : owner.getEmail();
431	        String household = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
432	        return telephone + "|" + email + "|" + household;
433	    }
434	
435	    /**
436	     * Whether {@code owner}'s whole {@link #identityKey} equals an existing owner's, which is the sole
437	     * duplicate condition: the previously separate telephone, email and household checks are now all
438	     * expressed through this one key, so only an exact full-key match is a duplicate and a create that
439	     * trips it is rejected with {@code 409 CONFLICT}.
440	     */
441	    private boolean isDuplicate(Owner owner) {
442	        String key = owner.getIdentityKey();
443	        return this.clinicService.findAllOwners().stream()
444	            .map(Owner::getIdentityKey)
445	            .filter(existing -> existing != null)
446	            .anyMatch(key::equals);
447	    }
448	
449	    /** Common street-type abbreviations expanded during address normalization. */
450	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
451	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
452	
453	    /**
454	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
455	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
456	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
457	     * string when {@code address} is null or blank after normalization.
458	     */
459	    private static String normalizeAddress(String address) {
460	        if (address == null) {
461	            return "";
462	        }
463	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
464	        if (collapsed.isEmpty()) {
465	            return "";
466	        }
467	        StringBuilder sb = new StringBuilder(collapsed.length());
468	        for (String token : collapsed.split(" ")) {
469	            if (sb.length() > 0) {
470	                sb.append(' ');
471	            }
472	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
473	        }
474	        return sb.toString();
475	    }
476	
477	    /**
478	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
479	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
480	     */
481	    private static String normalizeHouseholdField(String value) {
482	        if (value == null) {
483	            return "";
484	        }
485	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
486	    }
487	
488	    /**
489	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
490	     * same address compared case-insensitively with collapsed whitespace.
491	     */
492	    private List<Owner> findHousemates(Owner owner) {
493	        String lastName = normalizeHouseholdField(owner.getLastName());
494	        String address = normalizeHouseholdField(owner.getAddress());
495	        return this.clinicService.findAllOwners().stream()
496	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
497	                && normalizeHouseholdField(existing.getAddress()).equals(address))
498	            .toList();
499	    }
500	
501	    /**
502	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
503	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
504	     */
505	    private int countHouseholdMembers(Owner owner) {
506	        return findHousemates(owner).size() + 1;
507	    }
508	
509	    /**
510	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
511	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
512	     * deterministically from those normalized fields so housemates always resolve to the same value,
513	     * regardless of registration order.
514	     */
515	    private static String householdId(Owner owner) {
516	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
517	            + normalizeHouseholdField(owner.getAddress());
518	        try {
519	            byte[] digest = MessageDigest.getInstance("SHA-256")
520	                .digest(key.getBytes(StandardCharsets.UTF_8));
521	            StringBuilder sb = new StringBuilder(24);
522	            for (int i = 0; i < 12; i++) {
523	                sb.append(String.format("%02X", digest[i]));
524	            }
525	            return sb.toString();
526	        }
527	        catch (NoSuchAlgorithmException e) {
528	            throw new IllegalStateException("SHA-256 not available", e);
529	        }
530	    }
531	}
